#include <benchmark/benchmark.h>
#include "tick-generator.hpp"

#include <cstdint>
#include <vector>

// ---------------------------------------------------------------------------
// Corpus: generated once per process, shared by every variant.
// Never generate inside the timed loop.
// ---------------------------------------------------------------------------
static const std::vector<Tick>& corpus() {
    static const std::vector<Tick> c = TickGenerator::corpus(1'000'000);
    return c;
}

static constexpr std::uint64_t kWindowNs = 30'000'000'000ULL;  // 30 s

// ---------------------------------------------------------------------------
// Variants under test. Replace the bodies with the real implementations.
// Each must expose: on_tick(ts, price, qty) and value().
// ---------------------------------------------------------------------------
struct RollingSumBucketed {
    void on_tick(std::int64_t, std::int64_t p, std::int64_t) { total_ += p; }
    std::int64_t value() const { return total_; }
    std::int64_t total_ = 0;
};

struct RollingSumDeque {
    void on_tick(std::int64_t, std::int64_t p, std::int64_t) { total_ += p; }
    std::int64_t value() const { return total_; }
    std::int64_t total_ = 0;
};

// ---------------------------------------------------------------------------
// One templated driver, instantiated per variant.
// ---------------------------------------------------------------------------
template <typename Agg>
static void BM_Aggregate(benchmark::State& state) {
    const auto& ticks = corpus();

    for (auto _ : state) {
        state.PauseTiming();
        Agg agg;                       // fresh state, untimed
        state.ResumeTiming();

        for (const Tick& t : ticks) {
            agg.on_tick(t.ts_ns, t.price, t.qty);
            benchmark::DoNotOptimize(agg.value());   // the optimiser barrier
        }
        benchmark::ClobberMemory();
    }

    state.SetItemsProcessed(state.iterations() * static_cast<std::int64_t>(ticks.size()));
    state.counters["ns/tick"] = benchmark::Counter(
        static_cast<double>(state.iterations() * ticks.size()),
        benchmark::Counter::kIsRate | benchmark::Counter::kInvert);
}

BENCHMARK(BM_Aggregate<RollingSumBucketed>)->Name("RollingSum/bucketed")->UseRealTime();
BENCHMARK(BM_Aggregate<RollingSumDeque>)->Name("RollingSum/deque")->UseRealTime();

BENCHMARK_MAIN();
